const item = $input.item.json;
const body = $('Drafting Email Webhook').first().json.body ?? {};

const stripCodeFence = (value) =>
  String(value || '')
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

const parseJson = (raw) => {
  const cleaned = stripCodeFence(raw);
  try {
    return JSON.parse(cleaned);
  } catch (error) {
    throw new Error(`Draft agent output is not valid JSON: ${cleaned}`);
  }
};

const extractEmail = (value) => {
  const raw = String(value || '').trim();
  const match = raw.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  return match?.[1] || raw || null;
};

const sourceEmail = body.source_email ?? {};
const currentDraft = body.current_draft ?? {};

if (!body.user_id) {
  throw new Error('Webhook body.user_id is required to save draft email');
}

const result = parseJson(item.output);
const now = new Date().toISOString();
const draftType = body.draft_type || result.draft_type || 'reply';
const fallbackTo = draftType === 'reply'
  ? extractEmail(sourceEmail.from || body.from)
  : extractEmail(sourceEmail.to || body.to);

return {
  json: {
    draft_id: body.draft_id || null,
    user_id: body.user_id,
    session_id: body.session_id || null,
    source_thread_id: sourceEmail.threadId || body.threadId || null,
    source_message_id: sourceEmail.id || body.id || body.messageId || null,
    draft_type: draftType,
    status: 'draft',
    to_email: result.to || currentDraft.to || fallbackTo,
    cc: result.cc ?? currentDraft.cc ?? sourceEmail.cc ?? body.cc ?? '',
    bcc: result.bcc ?? currentDraft.bcc ?? sourceEmail.bcc ?? body.bcc ?? '',
    subject: result.subject || currentDraft.subject || sourceEmail.subject || body.subject || '',
    body_text: result.body_text || result.message || currentDraft.body_text || sourceEmail.body || body.body || '',
    body_html: result.body_html || result.message || currentDraft.body_html || sourceEmail.htmlBody || body.htmlBody || '',
    attachments: Array.isArray(result.attachments)
      ? result.attachments
      : Array.isArray(currentDraft.attachments)
        ? currentDraft.attachments
        : Array.isArray(sourceEmail.attachments)
          ? sourceEmail.attachments
          : Array.isArray(body.attachments)
            ? body.attachments
            : [],
    source_email_payload: body,
    revision_note: body.revision_note || body.revision_instructions || null,
    sent_message_id: null,
    sent_at: null,
    created_at: now,
    updated_at: now,
  },
};

const drafts = $input.all().map((item) => item.json);

return {
  json: {
    drafts,
  },
};

const body = $json.body ?? {};
const currentDraft = body.current_draft ?? {};
const sourceEmail = body.source_email ?? {};
const now = new Date().toISOString();

const extractEmail = (value) => {
  const raw = String(value || '').trim();
  const match = raw.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  return match?.[1] || raw || null;
};

const normalizeUserId = (...values) => {
  for (const value of values) {
    if (typeof value !== 'string') continue;
    const trimmed = value.trim();
    if (!trimmed) continue;
    if (trimmed.toLowerCase() === 'unknown') continue;
    return trimmed;
  }
  return null;
};

const googleAccessToken =
  body.google_access_token ||
  body.google_token?.access_token ||
  null;
const resolvedUserId = normalizeUserId(body.user_id, sourceEmail.user_id, currentDraft.user_id);

if (!resolvedUserId) {
  throw new Error('Valid user_id is required to send email');
}

if (!body.draft_id) {
  throw new Error('Webhook body.draft_id is required to send draft email');
}

if (!googleAccessToken) {
  throw new Error('Google access token is required to send email');
}

const toEmail = extractEmail(
  currentDraft.to ||
  currentDraft.to_email ||
  sourceEmail.from ||
  body.to
);

if (!toEmail) {
  throw new Error('Draft recipient is required before sending email');
}

const cc = currentDraft.cc || sourceEmail.cc || body.cc || '';
const bcc = currentDraft.bcc || sourceEmail.bcc || body.bcc || '';
const subject = currentDraft.subject || sourceEmail.subject || body.subject || '';
const bodyHtml = currentDraft.body_html || currentDraft.htmlBody || sourceEmail.htmlBody || body.htmlBody || '';
const bodyText = currentDraft.body_text || sourceEmail.body || body.body || '';
const messageBody = bodyHtml || bodyText;
const inReplyTo = sourceEmail.messageId || sourceEmail.id || body.messageId || body.id || '';

const headerLines = [
  `To: ${toEmail}`,
  cc ? `Cc: ${cc}` : null,
  bcc ? `Bcc: ${bcc}` : null,
  `Subject: ${subject}`,
  inReplyTo ? `In-Reply-To: <${inReplyTo}>` : null,
  inReplyTo ? `References: <${inReplyTo}>` : null,
  'MIME-Version: 1.0',
  'Content-Type: text/html; charset=utf-8',
].filter((line) => line !== null);

const rawEmail = `${headerLines.join('\r\n')}\r\n\r\n${messageBody}`;
const raw = Buffer.from(rawEmail)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return {
  json: {
    draft_id: body.draft_id,
    user_id: resolvedUserId,
    session_id: body.session_id || null,
    source_thread_id: sourceEmail.threadId || body.threadId || null,
    source_message_id: sourceEmail.id || body.id || body.messageId || null,
    draft_type: body.draft_type || currentDraft.draft_type || 'reply',
    status: 'sent',
    to_email: toEmail,
    cc,
    bcc,
    subject,
    body_text: bodyText,
    body_html: messageBody,
    attachments: Array.isArray(currentDraft.attachments)
      ? currentDraft.attachments
      : Array.isArray(sourceEmail.attachments)
        ? sourceEmail.attachments
        : [],
    source_email_payload: body,
    revision_note: body.revision_note || body.revision_instructions || null,
    sent_message_id: null,
    sent_at: now,
    updated_at: now,
    google_access_token: googleAccessToken,
    gmail_raw: raw,
  },
};

const sendResponse = $json;
const draft = $('Prepare Send Payload').first().json;

return {
  json: {
    ...draft,
    sent_message_id: sendResponse.id || sendResponse.messageId || null,
    provider_response: sendResponse,
  },
};

